def existing_assignments(apps, schema_editor):
    """Tasks that already have executors: their urgency days started when the executors arrived."""
    Issue = apps.get_model("db", "Issue")
    IssueAssignee = apps.get_model("db", "IssueAssignee")
    TaskAssignment = apps.get_model("atlante", "TaskAssignment")
    rome = ZoneInfo("Europe/Rome")
    latest = {}
    for issue_id, created_at in IssueAssignee._base_manager.filter(deleted_at__isnull=True).values_list(
        "issue_id", "created_at"
    ):
        if issue_id not in latest or created_at > latest[issue_id]:
            latest[issue_id] = created_at
    rows = [
        TaskAssignment(
            issue_id=issue_id,
            assigned_on=latest[issue_id].astimezone(rome).date() if issue_id in latest else None,
            priority=priority or "",
        )
        for issue_id, priority in Issue._base_manager.filter(deleted_at__isnull=True).values_list("id", "priority")
    ]
    TaskAssignment.objects.bulk_create(rows, batch_size=1000, ignore_conflicts=True)


